// === Tab: mySketch.js ===
/*

Flip City by megamitts for #WCCC Flip / City  (Hold left mouse to Flip)


AI disclosure: I'm only just starting to look at Shaders and I'm an old man so I haven't got as much time 
as you whippersnappers to learn the voodoo! (old man shouts at GPU) So AI did do the bulk. Give me Fully Automated Luxury 
Communism or give me death...either way I'm not going into work that Monday!

I did tweak a hell of a lot of the code though - removing stuff that just didn't work, 
changing colours, adding timings to the building lights, changing the star speed (nice parallax scrolling!) 
and adding a moon that moves slowly across the canvas and converted the code to use p5js2 correctly. I've learnt quite a bit 
tweaking away at this prototype. Stuff that I'll surely forget when I go to sleep! 
I reckon I could have done this all without shaders, but it's something I do want to get my head around eventually.

I also added a faint blur to give that night time feel that GenXers like myself get with too bright headlights. For
God's sake, dip those mofos!

Off topic: The song Flip City (https://www.youtube.com/watch?v=RMs5nMMC2ds) is one of the best tracks on the soundtrack 
for Ghostbusters 2. 
If you've never listened to this soundtrack then go ahead - it's a late 80s cheesy masterpiece.

*/


let cityShader;

let flipAngle = 0;









async function setup() {

  createCanvas(
    400,
    400,
    WEBGL
  );



  pixelDensity(1);

  cityShader = await loadShader('https://openprocessing.org/sketch/3007708/files/shader.vert',
      'shader.frag'
    );

  noStroke();
}




function draw() {

  shader(cityShader);


  let targetFlip =
    ((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))
      ? PI
      : 0;


  flipAngle =
    lerp(
      flipAngle,
      targetFlip,
      0.06
    );




  cityShader.setUniform(
    "u_resolution",
    [
      width,
      height
    ]
  );


  cityShader.setUniform(
    "u_time",
    millis() / 1000.0
  );


  cityShader.setUniform(
    "u_flip",
    flipAngle
  );




  beginShape();

  vertex(
    -width / 2,
    -height / 2
  );

  vertex(
    width / 2,
    -height / 2
  );

  vertex(
    width / 2,
    height / 2
  );

  vertex(
    -width / 2,
    height / 2
  );

  endShape(CLOSE);

  filter(BLUR,1.5);
}

// === Tab: shader.vert ===


  precision highp float;

  attribute vec3 aPosition;

  uniform vec2 u_resolution;

  void main() {


    vec2 position = aPosition.xy;

    position /= u_resolution * 0.5;

    // p5 Y increases downwards.
    // OpenGL Y increases upwards.

    position.y = -position.y;

    gl_Position = vec4(position, 0.0, 1.0);
  }


// === Tab: shader.frag ===
// =====================================================
// FRAGMENT SHADER
// =====================================================



  precision highp float;

  uniform vec2 u_resolution;
  uniform float u_time;
  uniform float u_flip;

  #define PI 3.14159265359


  // ===================================================
  // RANDOM
  // ===================================================

  float hash21(vec2 p) {

    p = fract(
      p * vec2(123.34, 456.21)
    );

    p += dot(
      p,
      p + 45.32
    );

    return fract(
      p.x * p.y
    );
  }


  // ===================================================
  // 2D ROTATION
  // ===================================================

  vec2 rotate(
    vec2 p,
    float angle
  ) {

    float c = cos(angle);
    float s = sin(angle);

    return mat2(
      c, -s,
      s,  c
    ) * p;
  }


  // ===================================================
  // MAIN
  // ===================================================

  void main() {

    // -----------------------------------------------
    // SCREEN COORDINATES
    // -----------------------------------------------

    vec2 uv =
      gl_FragCoord.xy /
      u_resolution.xy;

    vec2 p =
      uv * 2.0 - 1.0;

    // Correct aspect ratio

    p.x *=
      u_resolution.x /
      u_resolution.y;


    // -----------------------------------------------
    // FLIP THE WORLD
    // -----------------------------------------------

    p = rotate(
      p,
      u_flip
    );


    // -----------------------------------------------
    // SKY
    // -----------------------------------------------

    vec3 skyTop =
      vec3(
        0.003,
        0.006,
        0.018
      );

    vec3 skyBottom =
      vec3(
        0.035,
        0.045,
        0.09
      );

    float skyGradient =
      smoothstep(
        -0.1,
        0.9,
        p.y
      );

    vec3 colour =
      mix(
        skyBottom,
        skyTop,
        skyGradient
      );


// =================================================
// STAR FIELD
// =================================================

vec3 stars = vec3(0.0);


// -------------------------------------------------
// Distant stars
// -------------------------------------------------

vec2 stars1 =
  p;

stars1.x -=
  u_time * 0.008;

vec2 grid1 =
  floor(stars1 * 55.0);

float random1 =
  hash21(grid1);

if (random1 > 0.985) {

  stars +=
    vec3(0.45, 0.5, 0.65);
}


// -------------------------------------------------
// Closer stars
// -------------------------------------------------

vec2 stars2 =
  p;

stars2.x -=
  u_time * 0.0025;

vec2 grid2 =
  floor(stars2 * 100.0);

float random2 =
  hash21(grid2);

if (random2 > 0.99) {

  float twinkle =
    0.7 +
    0.3 *
    sin(
      u_time * 2.0 +
      grid2.x
    );

  stars +=
    vec3(
      0.8,
      0.85,
      1.0
    )
    * twinkle;
}


colour += stars;


    // =================================================
    // CITY
    // =================================================

    float horizon =
      0.16;


    if (p.y < horizon) {


      // ---------------------------------------------
      // PERSPECTIVE
      // ---------------------------------------------

      float depth =
        1.0 /
        max(
          0.025,
          horizon - p.y
        );


      // ---------------------------------------------
      // GROUND
      // ---------------------------------------------

      vec2 ground;

      ground.x =
        p.x * depth;

      ground.y =
        depth;


      // ---------------------------------------------
      // ROAD
      // ---------------------------------------------

      float roadWidth =
        0.22;

      float road =
        smoothstep(
          roadWidth,
          roadWidth - 0.025,
          abs(ground.x)
        );


      vec3 roadColour =
        vec3(
          0.008,
          0.009,
          0.014
        );


      vec3 pavement =
        vec3(
          0.01,
          0.020,
          0.028
        );


      colour =
        mix(
          pavement,
          roadColour,
          road
        );


      // =================================================
      // ROAD LINES
      // =================================================

      float roadDash =
        step(
          0.38,
          fract(
            ground.y * 0.98
          )
        );


      float centreLine =
        smoothstep(
          0.018,
          0.0,
          abs(ground.x)
        );


      centreLine *=
        roadDash *
        road;


      colour +=
        vec3(
          0.8,
          0.65,
          0.25
        )
        * centreLine
        * 0.8;


      // =================================================
      // BUILDINGS
      // =================================================

      // Buildings are arranged in repeating blocks.

      float buildingScale =
        4.0;

      float bx =
        p.x * buildingScale;

      float buildingID =
        floor(bx);


      float buildingSide =
        sign(
          buildingID + 0.5
        );


      // Distance from centre of building

      float localX =
        fract(bx) - 0.5;


      // Keep buildings away from the road

      float sideMask =
        step(
          roadWidth,
          abs(p.x)
        );


      // Random building height

      float buildingRandom =
        hash21(
          vec2(
            buildingID,
            17.0
          )
        );


      float buildingHeight =
        0.35 +
        buildingRandom * 1.6;


      // Perspective makes the buildings rise
      // from the ground towards the camera.

      float buildingTop =
        smoothstep(
          buildingHeight + 0.03,
          buildingHeight,
          depth * 0.16
        );


      float buildingWidth =
        smoothstep(
          0.47,
          0.40,
          abs(localX)
        );


      float buildingMask =
        buildingWidth *
        buildingTop *
        sideMask;


      // Only show buildings on the sides

      float side =
        smoothstep(
          0.22,
          0.42,
          abs(p.x)
        );


      buildingMask *= side;


      // ---------------------------------------------
      // BUILDING COLOUR
      // ---------------------------------------------

      vec3 buildingColour =
        vec3(
          1.008,
          0.011,
          0.020
        );


      buildingColour +=
        buildingRandom *
        vec3(
          0.012,
          0.012,
          0.022
        );


      colour =
        mix(
          colour,
          buildingColour,
          buildingMask
        );


      // =================================================
      // BUILDING WINDOWS
      // =================================================

      vec2 windowUV;

      windowUV.x =
        localX * 7.0;

      windowUV.y =
        depth * 1.9;


      vec2 windowCell =
        floor(windowUV);


      vec2 windowPosition =
        fract(windowUV);


      float windowRandom =
        hash21(
          windowCell +
          vec2(
            buildingID * 31.0,
            73.0
          )
        );


      // Most windows are dark

      float windowOn =
        step(
          0.68*sin(u_time*0.35),
          windowRandom
        );


      // Window shape

      float windowShape =
        step(
          0.18,
          windowPosition.x
        )
        *
        step(
          0.18,
          windowPosition.y
        )
        *
        step(
          windowPosition.x,
          0.82
        )
        *
        step(
          windowPosition.y,
          0.82
        );


      float windows =
        windowOn *
        windowShape *
        buildingMask;


      // Warm windows

      vec3 warmLight =
        vec3(
          1.0,
          0.48,
          0.12
        );


      colour +=
        warmLight *
        windows *
        0.9;


      // Occasional blue windows

      float blueWindow =
        step(
          0.94,
          windowRandom
        );


      colour +=
        vec3(
          0.12,
          0.35,
          1.0
        )
        *
        blueWindow
        *
        windowShape
        *
        buildingMask;


      // =================================================
      // MOVING VEHICLE LIGHTS
      // =================================================

      float trafficPosition =
        fract(
          u_time * 0.08
          +
          buildingRandom
        );


      float vehicle =
        smoothstep(
          0.02,
          0.0,
          abs(
            fract(
              ground.y * 0.035
              + trafficPosition
            ) - 0.5
          )
        );


      // Headlights

      float headlights =
        vehicle *
        road *
        smoothstep(
          0.18,
          0.0,
          abs(ground.x)
        );


      colour +=
        vec3(
          1.0,
          0.85,
          0.55
        )
        *
        headlights
        *
        0.8;


      // // =================================================
      // // SIDE STREET LIGHTS
      // // =================================================

      // float streetGrid =
      //   floor(
      //     ground.y * 0.08
      //   );


      // float streetRandom =
      //   hash21(
      //     vec2(
      //       streetGrid,
      //       91.0
      //     )
      //   );


      // float lamp =
      //   smoothstep(
      //     0.035,
      //     0.0,
      //     abs(
      //       fract(
      //         ground.y * 1.08
      //       ) - 0.5
      //     )
      //   );


      // float lampSide =
      //   smoothstep(
      //     0.55,
      //     0.9,
      //     abs(ground.x)
      //   );


      // colour +=
      //   vec3(
      //     1.0,
      //     0.45,
      //     0.12
      //   )
      //   *
      //   lamp
      //   *
      //   lampSide
      //   *
      //   streetRandom
      //   *
      //   0.35;


      // =================================================
      // DISTANT CITY GLOW
      // =================================================

      float cityGlow =
        exp(
          -abs(
            p.y - horizon
          )
          * 42.0
        );


      colour +=
        vec3(
          0.8,
          0.07,
          0.025
        )
        *
        cityGlow;


    }


    // =================================================
    // HORIZON
    // =================================================

    float horizonGlow =
      exp(
        -abs(
          p.y - horizon
        )
        * 35.0
      );


    colour +=
      vec3(
        0.35,
        0.12,
        0.04
      )
      *
      horizonGlow
      *
      0.35;


    // =================================================
    // VIGNETTE
    // =================================================

    float vignette =
      1.0 -
      smoothstep(
        0.35,
        1.4,
        length(p)
      );


    colour *=
      vignette;


// ------------------------------------------------
// MOON
// ------------------------------------------------

float moonX = mod(u_time * 0.005, 2.8) - 0.9;

vec2 moonPosition = vec2(moonX, 0.85);
// vec2 moonPosition = vec2(-0.9+u_time*0.005, 0.85);

float moonDistance = distance(p, moonPosition);

// Moon radius
float moonRadius = 0.09;

// Soft edge
float moon = 1.0 - smoothstep(
  moonRadius - 0.01,
  moonRadius,
  moonDistance
);

// Draw white moon
colour = mix(
  colour,
  vec3(0.8,0.8,0.8),
  moon
);


    // =================================================
    // FINAL OUTPUT
    // =================================================

    gl_FragColor =
      vec4(
        colour,
        1.0
      );
  }

